module benchmark/solution
import std/env (getArgs)
import std/fs (readFile)
import std/string (split, trim, stringToInt)
import std/list (foldl)
import std/option (Option, Some, None)

func sumLines(lines: [string]) -> int =
  foldl(func(acc: int, line: string) -> int {
    let trimmed = trim(line);
    if trimmed == "" then acc
    else match stringToInt(trimmed) {
      Some(n) => acc + n,
      None => acc
    }
  }, 0, lines)

export func main() -> () ! {IO, FS, Env} {
  let args = getArgs();
  match args {
    filename :: _ => {
      let content = readFile(filename);
      let lines = split(content, "\n");
      let total = sumLines(lines);
      println(show(total))
    },
    _ => println("Usage: solution <filename>")
  }
}

