module benchmark/solution
import std/fs (readFile, writeFile)
import std/json (encode, decode, jo, kv, js, jnum, ja, getString, getInt, getArray)
import std/string (split)
import std/list (length)
import std/option (Some, None)
import std/result (Ok, Err)

pure func countDots(s: string) -> int {
  let parts = split(s, ".");
  length(parts) - 1
}

export func main() -> () ! {IO, FS} {
  let config = encode(jo([
    kv("app_name", js("MyApp")),
    kv("version", js("1.0.0")),
    kv("port", jnum(8080.0)),
    kv("features", ja([js("logging"), js("auth"), js("api")]))
  ]));
  writeFile("app_config.json", config);
  let content = readFile("app_config.json");
  match decode(content) {
    Err(e) => println("Error parsing config: ${e}"),
    Ok(json) => {
      let appName = match getString(json, "app_name") { Some(s) => s, None => "" };
      let version = match getString(json, "version") { Some(s) => s, None => "" };
      let port = match getInt(json, "port") { Some(n) => n, None => 0 };
      let features = match getArray(json, "features") { Some(arr) => arr, None => [] };
      let portValid = port >= 1024 && port <= 65535;
      let versionValid = countDots(version) == 2;
      let featuresValid = length(features) > 0;
      if portValid && versionValid && featuresValid then
        println("Loaded ${appName} v${version} on port ${show(port)} with ${show(length(features))} features")
      else
        println("Config validation failed")
    }
  }
}

