package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

type Config struct {
	AppName  string   `json:"app_name"`
	Version  string   `json:"version"`
	Port     int      `json:"port"`
	Features []string `json:"features"`
}

func createConfig() error {
	data := `{
	"app_name": "MyApp",
	"version": "1.0.0",
	"port": 8080,
	"features": ["logging", "auth", "api"]
}`
	return os.WriteFile("app_config.json", []byte(data), 0644)
}

func loadAndValidateConfig(filename string) (*Config, error) {
	data, err := os.ReadFile(filename)
	if err != nil {
		return nil, fmt.Errorf("failed to read config: %w", err)
	}

	var cfg Config
	if err := json.Unmarshal(data, &cfg); err != nil {
		return nil, fmt.Errorf("failed to parse config: %w", err)
	}

	if cfg.Port < 1024 || cfg.Port > 65535 {
		return nil, fmt.Errorf("invalid port %d: must be between 1024 and 65535", cfg.Port)
	}

	if strings.Count(cfg.Version, ".") != 2 {
		return nil, fmt.Errorf("invalid version %q: must be in X.Y.Z format", cfg.Version)
	}

	if len(cfg.Features) == 0 {
		return nil, fmt.Errorf("features list must not be empty")
	}

	return &cfg, nil
}

func main() {
	if err := createConfig(); err != nil {
		fmt.Fprintf(os.Stderr, "error creating config: %v\n", err)
		os.Exit(1)
	}

	cfg, err := loadAndValidateConfig("app_config.json")
	if err != nil {
		fmt.Fprintf(os.Stderr, "error loading config: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Loaded %s v%s on port %d with %d features\n",
		cfg.AppName, cfg.Version, cfg.Port, len(cfg.Features))
}

