function loadAndValidateConfig(filePath) {
  const raw = readFileSync(filePath, 'utf8');
  const cfg = JSON.parse(raw);

  if (cfg.port < 1024 || cfg.port > 65535) {
    throw new Error(`Invalid port: ${cfg.port}`);
  }

  if ((cfg.version.match(/\./g) ?? []).length !== 2) {
    throw new Error(`Invalid version format: ${cfg.version}`);
  }

  if (!Array.isArray(cfg.features) || cfg.features.length === 0) {
    throw new Error('Features list must not be empty');
  }

  return cfg;
}

const cfg = loadAndValidateConfig(configPath);
console.log(`Loaded ${cfg.app_name} v${cfg.version} on port ${cfg.port} with ${cfg.features.length} features`);

