from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class LeafType:
    pass


@dataclass(frozen=True)
class Node:
    value: int
    left: Tree
    right: Tree


type Tree = LeafType | Node

Leaf = LeafType()


def insert(tree: Tree, value: int) -> Tree:
    match tree:
        case LeafType():
            return Node(value, Leaf, Leaf)
        case Node(node_value, left, right):
            if value < node_value:
                return Node(node_value, insert(left, value), right)
            if value > node_value:
                return Node(node_value, left, insert(right, value))
            return tree


def contains(tree: Tree, value: int) -> bool:
    match tree:
        case LeafType():
            return False
        case Node(node_value, left, right):
            if value == node_value:
                return True
            if value < node_value:
                return contains(left, value)
            return contains(right, value)


def size(tree: Tree) -> int:
    match tree:
        case LeafType():
            return 0
        case Node(_, left, right):
            return 1 + size(left) + size(right)


def isBST(tree: Tree, lower: int, upper: int) -> bool:
    match tree:
        case LeafType():
            return True
        case Node(value, left, right):
            return (
                lower < value < upper
                and isBST(left, lower, value)
                and isBST(right, value, upper)
            )


def insertPreservesBST(value: int) -> bool:
    return isBST(insert(Leaf, value), -999999, 999999)


def insertThenFind(value: int) -> bool:
    return contains(insert(Leaf, value), value)


def bool_text(value: bool) -> str:
    return "true" if value else "false"


def main() -> None:
    tree = insert(insert(insert(Leaf, 5), 3), 7)
    outputs = [
        str(size(tree)),
        bool_text(contains(tree, 3)),
        bool_text(contains(tree, 4)),
        bool_text(isBST(tree, -999999, 999999)),
        bool_text(insertPreservesBST(42)),
        bool_text(insertThenFind(42)),
    ]
    print("\n".join(outputs))


if __name__ == "__main__":
    main()

