module benchmark/solution
-- DO NOT CHANGE THE MODULE DECLARATION ABOVE!
import std/string (substring, length)

-- Convert integer to Roman numeral string
pure func toRoman(n: int) -> string =
  let pairs = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
               (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
               (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")] in
  buildRoman(n, pairs)

pure func buildRoman(n: int, pairs: [(int, string)]) -> string =
  match pairs {
    [] => "",
    (val, sym) :: rest =>
      if n >= val then "${sym}${buildRoman(n - val, pairs)}"
      else buildRoman(n, rest)
  }

-- Convert Roman numeral string to integer
pure func fromRoman(s: string) -> int =
  parseRoman(s, 0)

pure func parseRoman(s: string, acc: int) -> int =
  if s == "" then acc
  else
    let first = romanCharVal(substring(s, 0, 1)) in
    let rest = substring(s, 1, length(s)) in
    if rest == "" then acc + first
    else
      let second = romanCharVal(substring(s, 1, 2)) in
      if second > first then parseRoman(substring(s, 2, length(s)), acc + second - first)
      else parseRoman(rest, acc + first)

pure func romanCharVal(c: string) -> int =
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0
  }

-- Proof: roundtrip fromRoman(toRoman(n)) == n for n in 1..3999
pure func roundtrip(n: int) -> bool =
  fromRoman(toRoman(n)) == n

-- Proof: distinct integers produce distinct encodings
pure func distinctEncoding(a: int, b: int) -> bool =
  if a == b then true
  else toRoman(a) != toRoman(b)

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

codeSamples.python:
ROMAN_VALUES: tuple[tuple[int, str], ...] = (
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
)

SYMBOL_VALUES: dict[str, int] = {
    "I": 1,
    "V": 5,
    "X": 10,
    "L": 50,
    "C": 100,
    "D": 500,
    "M": 1000,
}


def toRoman(number: int) -> str:
    if not 1 <= number <= 3999:
        raise ValueError("Roman numerals are supported for 1 through 3999")

    result: list[str] = []
    remaining = number
    for value, symbol in ROMAN_VALUES:
        count, remaining = divmod(remaining, value)
        result.append(symbol * count)
    return "".join(result)


def fromRoman(numeral: str) -> int:
    if not numeral:
        raise ValueError("Roman numeral must not be empty")

    total = 0
    index = 0
    while index < len(numeral):
        current = SYMBOL_VALUES.get(numeral[index])
        if current is None:
            raise ValueError(f"Invalid Roman numeral symbol: {numeral[index]}")

        if index + 1 < len(numeral):
            next_value = SYMBOL_VALUES.get(numeral[index + 1])
            if next_value is None:
                raise ValueError(
                    f"Invalid Roman numeral symbol: {numeral[index + 1]}"
                )
            if current < next_value:
                total += next_value - current
                index += 2
                continue

        total += current
        index += 1

    if not 1 <= total <= 3999 or toRoman(total) != numeral:
        raise ValueError("Roman numeral is not canonical")

    return total


def roundtrip(number: int) -> bool:
    return fromRoman(toRoman(number)) == number


def distinctEncoding(first: int, second: int) -> bool:
    if first == second:
        return True
    return toRoman(first) != toRoman(second)


def format_bool(value: bool) -> str:
    return str(value).lower()


def main() -> None:
    outputs = (
        toRoman(1994),
        toRoman(58),
        toRoman(3999),
        str(fromRoman("MCMXCIV")),
        str(fromRoman("LVIII")),
        format_bool(roundtrip(2024)),
        format_bool(distinctEncoding(4, 6)),
    )
    print("\n".join(outputs))


if __name__ == "__main__":
    main()

