module benchmark/solution
import std/fs (readFile, writeFile)
import std/string (split, trim, contains, stringToInt)
import std/list (map, filter, foldl, length)
import std/json (encode, jo, ja, kv, js, jnum)
import std/option (Option, Some, None)

-- Validate a row: age must be positive integer, email must contain @
pure func isValidRow(name: string, ageStr: string, email: string) -> bool {
  let validEmail = contains(email, "@");
  let validAge = match stringToInt(trim(ageStr)) {
    Some(n) => n > 0,
    None => false
  };
  validEmail && validAge
}

-- Parse a single CSV data row into a JSON object string, returning None if invalid
pure func parseRow(row: string) -> Option[string] {
  let fields = split(row, ",");
  match fields {
    name :: ageStr :: email :: _ => {
      let n = trim(name);
      let a = trim(ageStr);
      let e = trim(email);
      if isValidRow(n, a, e) then
        match stringToInt(a) {
          Some(age) => Some(encode(jo([kv("name", js(n)), kv("age", jnum(intToFloat(age))), kv("email", js(e))]))),
          None => None
        }
      else None
    },
    _ => None
  }
}

-- Collect valid row JSON strings from data rows
func collectRows(rows: [string], acc: [string]) -> [string] =
  match rows {
    [] => acc,
    row :: rest => {
      let trimmed = trim(row);
      if trimmed == "" then collectRows(rest, acc)
      else match parseRow(trimmed) {
        Some(jsonStr) => collectRows(rest, acc ++ [jsonStr]),
        None => collectRows(rest, acc)
      }
    }
  }

-- Build JSON array string from list of JSON object strings
func buildJsonArray(items: [string]) -> string {
  let inner = foldl(func(acc: string, item: string) -> string {
    if acc == "" then item else "${acc},${item}"
  }, "", items);
  "[${inner}]"
}

export func main() -> () ! {IO, FS} {
  -- Create the input CSV file
  writeFile("users.csv", "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com\n");

  -- Read the CSV file
  let content = readFile("users.csv");
  let lines = split(content, "\n");

  -- Skip header row (first line), process data rows
  let dataRows = match lines {
    _ :: rest => rest,
    [] => []
  };

  -- Collect valid rows
  let validJsonRows = collectRows(dataRows, []);
  let count = length(validJsonRows);

  -- Build JSON array
  let jsonOutput = buildJsonArray(validJsonRows);

  -- Write JSON to file
  writeFile("users.json", jsonOutput);

  -- Print result
  println("Converted ${show(count)} valid rows to users.json")
}

