package main

import (
	"encoding/csv"
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type User struct {
	Name  string `json:"name"`
	Age   int    `json:"age"`
	Email string `json:"email"`
}

func main() {
	csvContent := "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com\n"
	if err := os.WriteFile("users.csv", []byte(csvContent), 0644); err != nil {
		fmt.Fprintf(os.Stderr, "Error writing CSV: %v\n", err)
		os.Exit(1)
	}

	f, err := os.Open("users.csv")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error opening CSV: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()

	reader := csv.NewReader(f)
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading CSV: %v\n", err)
		os.Exit(1)
	}

	if len(records) < 1 {
		fmt.Fprintf(os.Stderr, "Empty CSV\n")
		os.Exit(1)
	}

	var users []User
	for _, row := range records[1:] {
		if len(row) < 3 {
			continue
		}
		name := row[0]
		ageStr := row[1]
		email := row[2]

		age, err := strconv.Atoi(ageStr)
		if err != nil || age <= 0 {
			continue
		}

		if !strings.Contains(email, "@") {
			continue
		}

		users = append(users, User{Name: name, Age: age, Email: email})
	}

	data, err := json.MarshalIndent(users, "", "  ")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error marshaling JSON: %v\n", err)
		os.Exit(1)
	}

	if err := os.WriteFile("users.json", data, 0644); err != nil {
		fmt.Fprintf(os.Stderr, "Error writing JSON: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Converted %d valid rows to users.json\n", len(users))
}

