        return False

    return age > 0 and "@" in row.get("email", "")


def parse_valid_users(path: Path) -> list[dict[str, str | int]]:
    users: list[dict[str, str | int]] = []

    with path.open(newline="", encoding="utf-8") as csv_file:
        reader = csv.DictReader(csv_file)
        for row in reader:
            if not is_valid_row(row):
                continue

            users.append(
                {
                    "name": row["name"],
                    "age": int(row["age"]),
                    "email": row["email"],
                }
            )

    return users


def write_json_file(path: Path, data: list[dict[str, str | int]]) -> None:
    path.write_text(json.dumps(data, indent=2), encoding="utf-8")


def main() -> None:
    csv_path = Path("users.csv")
    json_path = Path("users.json")

    create_csv_file(csv_path)
    users = parse_valid_users(csv_path)
    write_json_file(json_path, users)

