package main

import "fmt"

type Result struct {
	value int
	err   string
	isOk  bool
}

func Ok(value int) Result {
	return Result{value: value, isOk: true}
}

func Err(msg string) Result {
	return Result{err: msg, isOk: false}
}

func validateAge(age int) Result {
	if age >= 0 && age <= 150 {
		return Ok(age)
	}
	return Err("Age out of range")
}

func calculateRetirementYears(age int) Result {
	if age < 65 {
		return Ok(65 - age)
	}
	return Err("Already retired")
}

func chain(age int) Result {
	r := validateAge(age)
	if !r.isOk {
		return r
	}
	return calculateRetirementYears(r.value)
}

func printResult(r Result) {
	if r.isOk {
		fmt.Printf("Years to retirement: %d\n", r.value)
	} else {
		fmt.Printf("Error: %s\n", r.err)
	}
}

func main() {
	printResult(chain(30))
	printResult(chain(70))
	printResult(chain(-5))
}

