from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Generic, TypeVar


T = TypeVar("T")
U = TypeVar("U")


@dataclass(frozen=True)
class Ok(Generic[T]):
    value: T


@dataclass(frozen=True)
class Err:
    message: str


type Result[T] = Ok[T] | Err


def validate_age(age: int) -> Result[int]:
    if 0 <= age <= 150:
        return Ok(age)
    return Err("Age out of range")


def calculate_retirement_years(age: int) -> Result[int]:
    if age < 65:
        return Ok(65 - age)
    return Err("Already retired")


def bind(result: Result[T], func: Callable[[T], Result[U]]) -> Result[U]:
    match result:
        case Ok(value):
            return func(value)
        case Err(message):
            return Err(message)


def format_result(result: Result[int]) -> str:
    match result:
        case Ok(value):
            return f"Years to retirement: {value}"
        case Err(message):
            return f"Error: {message}"


def main() -> None:
    for age in (30, 70, -5):
        result = bind(validate_age(age), calculate_retirement_years)
        print(format_result(result))


if __name__ == "__main__":
    main()

