// Algebraic Data Types for Tree
const Leaf = (value) => ({ type: 'Leaf', value });
const Node = (left, value, right) => ({ type: 'Node', left, value, right });

// Pattern matching via destructuring + exhaustiveness check
function matchTree(tree, { onLeaf, onNode }) {
  switch (tree.type) {
    case 'Leaf': return onLeaf(tree.value);
    case 'Node': return onNode(tree.left, tree.value, tree.right);
    default: throw new Error(`Non-exhaustive pattern: unknown type "${tree.type}"`);
  }
}

function tree_sum(tree) {
  return matchTree(tree, {
    onLeaf: (v) => v,
    onNode: (l, v, r) => tree_sum(l) + v + tree_sum(r),
  });
}

function find_max(tree) {
  return matchTree(tree, {
    onLeaf: (v) => v,
    onNode: (l, v, r) => {
      const leftMax = find_max(l);
      const rightMax = find_max(r);
      // Guard: pick the largest among left subtree max, current value, right subtree max
      return leftMax >= v && leftMax >= rightMax ? leftMax
           : rightMax >= v && rightMax >= leftMax ? rightMax
           : v;
    },
  });
}

const tree = Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)));

console.log(`Sum: ${tree_sum(tree)}`);
console.log(`Max: ${find_max(tree)}`);

