    left: Tree
    value: int
    right: Tree


type Tree = Leaf | Node


def tree_sum(tree: Tree) -> int:
    match tree:
        case Leaf(v):
            return v
        case Node(left, value, right):
            return tree_sum(left) + value + tree_sum(right)


def find_max(tree: Tree) -> int:
    match tree:
        case Leaf(v):
            return v
        case Node(Leaf(left_value), value, Leaf(right_value)):
            return max(left_value, value, right_value)
        case Node(Leaf(left_value), value, right) if left_value >= value:
            return max(left_value, find_max(right))
        case Node(Leaf(left_value), value, right):
            return max(value, left_value, find_max(right))
        case Node(left, value, Leaf(right_value)) if right_value >= value:
            return max(find_max(left), right_value)
        case Node(left, value, Leaf(right_value)):
            return max(find_max(left), value, right_value)
        case Node(left, value, right) if value >= find_max(left):
            return max(value, find_max(right))
        case Node(left, value, right):
            return max(find_max(left), value, find_max(right))


