type EventKind int

const (
	EventCall EventKind = iota
	EventTick
	EventArrive
)

type Event struct {
	kind  EventKind
	floor int
}

func transition(s State, e Event) State {
	switch s.kind {
	case StateIdle:
		switch e.kind {
		case EventCall:
			if e.floor == s.floor {
				return State{kind: StateDoorOpen, floor: s.floor, timer: 3}
			}
			return State{kind: StateMoving, floor: s.floor, target: e.floor}
		default:
			return s
		}
	case StateMoving:
		switch e.kind {
		case EventTick:
			return s
		case EventArrive:
			return State{kind: StateDoorOpen, floor: s.target, timer: 3}
		default:
			return s
		}
	case StateDoorOpen:
		switch e.kind {
		case EventTick:
			if s.timer > 1 {
				return State{kind: StateDoorOpen, floor: s.floor, timer: s.timer - 1}
			}
			return State{kind: StateIdle, floor: s.floor}
		default:
			return s
		}
	default:
		return s
	}
