  switch (state.type) {
    case 'Idle':
      switch (event.type) {
        case 'Call':
          return event.floor === state.floor
            ? State.DoorOpen(state.floor, 3)
            : State.Moving(state.floor, event.floor);
        case 'Tick':
        case 'Arrive':
          return state;
