package main

import "fmt"

// State variants
type StateKind int

const (
	StateIdle StateKind = iota
	StateHasCredit
	StateDispensing
)

type State struct {
	kind  StateKind
	value int // cents for HasCredit, change for Dispensing
}

// Event variants
type EventKind int

const (
	EventInsert EventKind = iota
	EventSelect
	EventDispenseDone
)

type Event struct {
	kind  EventKind
	value int // cents for Insert, code for Select
}

// Result
type Result struct {
	ok  bool
	state State
	err  string
}

func Ok(s State) Result    { return Result{ok: true, state: s} }
func Err(e string) Result  { return Result{ok: false, err: e} }

func price(code int) (int, bool) {
	switch code {
	case 1:
		return 125, true
	case 2:
		return 75, true
	case 3:
		return 100, true
	}
	return 0, false
}

func step(s State, e Event) Result {
	switch s.kind {
	case StateIdle:
		switch e.kind {
		case EventInsert:
			return Ok(State{kind: StateHasCredit, value: e.value})
		case EventSelect:
			return Err("no_credit")
		case EventDispenseDone:
			return Err("not_dispensing")
		}
	case StateHasCredit:
		switch e.kind {
		case EventInsert:
			return Ok(State{kind: StateHasCredit, value: s.value + e.value})
		case EventSelect:
			p, valid := price(e.value)
			if !valid {
				return Err("unknown_item")
			}
			if s.value < p {
				return Err("insufficient_funds")
			}
			return Ok(State{kind: StateDispensing, value: s.value - p})
		case EventDispenseDone:
			return Err("not_dispensing")
		}
	case StateDispensing:
		switch e.kind {
		case EventInsert:
			return Err("busy")
		case EventSelect:
			return Err("busy")
		case EventDispenseDone:
			return Ok(State{kind: StateIdle})
		}
	}
	return Err("unknown_state")
}

func printResult(r Result) {
	if r.ok {
		switch r.state.kind {
		case StateIdle:
			fmt.Println("ok: IDLE")
		case StateHasCredit:
			fmt.Printf("ok: CREDIT(%d)\n", r.state.value)
		case StateDispensing:
			fmt.Printf("ok: DISPENSING(%d)\n", r.state.value)
		}
	} else {
		fmt.Printf("err: %s\n", r.err)
	}
}

func main() {
	events := []Event{
		{EventInsert, 50},
		{EventSelect, 1},
		{EventInsert, 100},
		{EventSelect, 1},
		{EventInsert, 50},
		{EventDispenseDone, 0},
		{EventSelect, 2},
		{EventInsert, 100},
		{EventSelect, 2},
		{EventDispenseDone, 0},
	}

	state := State{kind: StateIdle}
	for _, e := range events {
		r := step(state, e)
		printResult(r)
		if r.ok {
			state = r.state
		}
	}
}

