const HasCredit = (cents) => ({ tag: 'HasCredit', cents });
const Dispensing = (change) => ({ tag: 'Dispensing', change });

// Event constructors
const Insert = (cents) => ({ tag: 'Insert', cents });
const Select = (code) => ({ tag: 'Select', code });
const DispenseDone = { tag: 'DispenseDone' };

// Item prices
const PRICES = { 1: 125, 2: 75, 3: 100 };

// Transition function using pattern matching via lookup table
function step(state, event) {
  const key = `${state.tag}:${event.tag}`;
  switch (key) {
    case 'Idle:Insert':
      return Ok(HasCredit(event.cents));
    case 'Idle:Select':
      return Err('no_credit');
    case 'Idle:DispenseDone':
      return Err('not_dispensing');

    case 'HasCredit:Insert':
      return Ok(HasCredit(state.cents + event.cents));
    case 'HasCredit:Select': {
      const price = PRICES[event.code];
      if (price === undefined) return Err('unknown_item');
      if (state.cents < price) return Err('insufficient_funds');
      return Ok(Dispensing(state.cents - price));
    }
    case 'HasCredit:DispenseDone':
      return Err('not_dispensing');

    case 'Dispensing:Insert':
      return Err('busy');
    case 'Dispensing:Select':
      return Err('busy');
    case 'Dispensing:DispenseDone':
      return Ok(Idle);

    default:
      return Err('unknown_transition');
  }
}

function printResult(result) {
  if (result.tag === 'Ok') {
    const s = result.value;
    switch (s.tag) {
      case 'Idle':
        console.log('ok: IDLE');
        break;
      case 'HasCredit':
        console.log(`ok: CREDIT(${s.cents})`);
        break;
      case 'Dispensing':
        console.log(`ok: DISPENSING(${s.change})`);
        break;
    }
  } else {
    console.log(`err: ${result.reason}`);
  }
}

// Simulation
const events = [
  Insert(50),
  Select(1),
  Insert(100),
  Select(1),
  Insert(50),
  DispenseDone,
  Select(2),
  Insert(100),
  Select(2),
  DispenseDone,
];

let state = Idle;
for (const event of events) {
  const result = step(state, event);
  printResult(result);
  if (result.tag === 'Ok') {
    state = result.value;
  }
}

