from dataclasses import dataclass
from typing import Union, Generic, TypeVar

# --- Data Types for State, Event, Result ---

# State
@dataclass
class Idle:
    pass

@dataclass
class HasCredit:
    cents: int

@dataclass
class Dispensing:
    change: int

State = Union[Idle, HasCredit, Dispensing]

# Event
@dataclass
class Insert:
    cents: int

@dataclass
class Select:
    code: int

@dataclass
class DispenseDone:
    pass

Event = Union[Insert, Select, DispenseDone]

# Result
T = TypeVar('T')
E = TypeVar('E')

@dataclass
class Ok(Generic[T]):
    value: T

@dataclass
class Err(Generic[E]):
    error: E

Result = Union[Ok[T], Err[E]]

# --- Price Mapping ---

PRICES = {1: 125, 2: 75, 3: 100}

# --- State Transition Function ---

def step(state: State, event: Event) -> Result[State, str]:
    match (state, event):
        # Idle State
        case Idle(), Insert(n):
            return Ok(HasCredit(n))
        case Idle(), Select(_):
            return Err("no_credit")
        case Idle(), DispenseDone():
            return Err("not_dispensing")

        # HasCredit State
        case HasCredit(c), Insert(n):
            return Ok(HasCredit(c + n))
        case HasCredit(c), Select(code):
            if code not in PRICES:
                return Err("unknown_item")
            price = PRICES[code]
            if c < price:
                return Err("insufficient_funds")
            else:
                return Ok(Dispensing(c - price))
        case HasCredit(_), DispenseDone():
            return Err("not_dispensing")

        # Dispensing State
        case Dispensing(_), Insert(_):
            return Err("busy")
        case Dispensing(_), Select(_):
            return Err("busy")
        case Dispensing(_), DispenseDone():
            return Ok(Idle())
    # The match is exhaustive, but adding a fallback for type checkers
    return Err("unhandled_transition")


# --- Main Simulation ---

def main():
    events = [
        Insert(50),
        Select(1),
        Insert(100),
        Select(1),
        Insert(50),
        DispenseDone(),
        Select(2),
        Insert(100),
        Select(2),
        DispenseDone(),
    ]

    state: State = Idle()

    for event in events:
        result = step(state, event)
        match result:
            case Ok(new_state):
                state = new_state
                match new_state:
                    case Idle():
                        print("ok: IDLE")
                    case HasCredit(n):
                        print(f"ok: CREDIT({n})")
                    case Dispensing(ch):
                        print(f"ok: DISPENSING({ch})")
            case Err(reason):
                print(f"err: {reason}")

if __name__ == "__main__":
    main()

