type Tree = Leaf(int) | Node(Tree, int, Tree)

pure func mapTree(fn: int -> int, tree: Tree) -> Tree =
  match tree {
    Leaf(v) => Leaf(fn(v)),
    Node(l, v, r) => Node(mapTree(fn, l), fn(v), mapTree(fn, r))
  }

pure func foldTree(fn: (int, int) -> int, acc: int, tree: Tree) -> int =
  match tree {
    Leaf(v) => fn(acc, v),
    Node(l, v, r) => foldTree(fn, fn(foldTree(fn, acc, l), v), r)
  }

pure func treeToList(tree: Tree) -> [int] =
  match tree {
    Leaf(v) => [v],
    Node(l, v, r) => treeToList(l) ++ [v] ++ treeToList(r)
  }

pure func treeDepth(tree: Tree) -> int =
  match tree {
    Leaf(_) => 1,
    Node(l, _, r) => {
      let ld = treeDepth(l);
      let rd = treeDepth(r);
      1 + if ld > rd then ld else rd
    }
  }

pure func double(x: int) -> int = x * 2
pure func add(a: int, b: int) -> int = a + b

pure func showList(xs: [int]) -> string =
  match xs {
    [] => "[]",
    _ => "[${joinInts(xs)}]"
  }

pure func joinInts(xs: [int]) -> string =
  match xs {
    [] => "",
    [x] => show(x),
    x :: rest => "${show(x)}, ${joinInts(rest)}"
  }

export func main() -> () ! {IO} {
  let tree = Node(Node(Leaf(1), 2, Leaf(3)), 4, Node(Leaf(5), 6, Leaf(7)));
  println(showList(treeToList(tree)));
  println(showList(treeToList(mapTree(double, tree))));
  println(show(foldTree(add, 0, tree)));
  println(show(treeDepth(tree)))
}

