package main

import (
	"fmt"
	"strings"
	"strconv"
)

type TreeKind int

const (
	LeafKind TreeKind = iota
	NodeKind
)

type Tree struct {
	kind  TreeKind
	value int
	left  *Tree
	right *Tree
}

func Leaf(v int) *Tree {
	return &Tree{kind: LeafKind, value: v}
}

func Node(left *Tree, v int, right *Tree) *Tree {
	return &Tree{kind: NodeKind, value: v, left: left, right: right}
}

func mapTree(fn func(int) int, t *Tree) *Tree {
	if t.kind == LeafKind {
		return Leaf(fn(t.value))
	}
	return Node(mapTree(fn, t.left), fn(t.value), mapTree(fn, t.right))
}

func foldTree(fn func(int, int) int, acc int, t *Tree) int {
	if t.kind == LeafKind {
		return fn(acc, t.value)
	}
	acc = foldTree(fn, acc, t.left)
	acc = fn(acc, t.value)
	acc = foldTree(fn, acc, t.right)
	return acc
}

func treeToList(t *Tree) []int {
	if t.kind == LeafKind {
		return []int{t.value}
	}
	result := treeToList(t.left)
	result = append(result, t.value)
	result = append(result, treeToList(t.right)...)
	return result
}

func treeDepth(t *Tree) int {
	if t.kind == LeafKind {
		return 1
	}
	leftDepth := treeDepth(t.left)
	rightDepth := treeDepth(t.right)
	if leftDepth > rightDepth {
		return leftDepth + 1
	}
	return rightDepth + 1
}

func formatList(nums []int) string {
	parts := make([]string, len(nums))
	for i, n := range nums {
		parts[i] = strconv.Itoa(n)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func main() {
	tree := Node(Node(Leaf(1), 2, Leaf(3)), 4, Node(Leaf(5), 6, Leaf(7)))

	double := func(x int) int { return x * 2 }
	add := func(a, b int) int { return a + b }

	fmt.Println(formatList(treeToList(tree)))
	fmt.Println(formatList(treeToList(mapTree(double, tree))))
	fmt.Println(foldTree(add, 0, tree))
	fmt.Println(treeDepth(tree))
}

