from __future__ import annotations
from typing import Union, Callable, List, TypeAlias

# 1. Define Tree type using simple classes for broader compatibility,
# though NamedTuple or dataclasses would also be excellent choices.
class Leaf:
    def __init__(self, value: int):
        self.value = value

class Node:
    def __init__(self, left: Tree, value: int, right: Tree):
        self.left = left
        self.value = value
        self.right = right

Tree: TypeAlias = Union[Leaf, Node]

# 2. Implement mapTree
def mapTree(fn: Callable[[int], int], tree: Tree) -> Tree:
    """Recursively apply a function to all values in a tree."""
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    elif isinstance(tree, Node):
        return Node(
            mapTree(fn, tree.left),
            fn(tree.value),
            mapTree(fn, tree.right)
        )
    # The following line is added to handle potential exhaustiveness checks
    # by type checkers, though in practice the above cases cover the Tree TypeAlias.
    raise TypeError("Invalid tree type")

# 3. Implement foldTree
def foldTree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    """Perform an in-order fold over the tree values."""
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    elif isinstance(tree, Node):
        # In-order traversal: process left, then current, then right
        left_acc = foldTree(fn, acc, tree.left)
        current_acc = fn(left_acc, tree.value)
        return foldTree(fn, current_acc, tree.right)
    raise TypeError("Invalid tree type")

# 4. Implement treeToList
def treeToList(tree: Tree) -> List[int]:
    """Convert a tree to a list of its values using in-order traversal."""
    if isinstance(tree, Leaf):
        return [tree.value]
    elif isinstance(tree, Node):
        return treeToList(tree.left) + [tree.value] + treeToList(tree.right)
    raise TypeError("Invalid tree type")

# 5. Implement treeDepth
def treeDepth(tree: Tree) -> int:
    """Return the maximum depth of the tree."""
    if isinstance(tree, Leaf):
        return 1
    elif isinstance(tree, Node):
        return 1 + max(treeDepth(tree.left), treeDepth(tree.right))
    raise TypeError("Invalid tree type")

# Helper functions for transformations
def double(x: int) -> int:
    return x * 2

def add(a: int, b: int) -> int:
    return a + b

def main():
    """Main function to run the tree transformations and print results."""
    # 6. Test with the specified tree structure
    tree = Node(
        Node(Leaf(1), 2, Leaf(3)),
        4,
        Node(Leaf(5), 6, Leaf(7))
    )

    # 7. Print the results as required
    # Expected: [1, 2, 3, 4, 5, 6, 7]
    print(treeToList(tree))

    # Expected: [2, 4, 6, 8, 10, 12, 14]
    mapped_tree = mapTree(double, tree)
    print(treeToList(mapped_tree))

    # Expected: 28
    total_sum = foldTree(add, 0, tree)
    print(total_sum)

    # Expected: 3
    depth = treeDepth(tree)
    print(depth)

if __name__ == "__main__":
    main()
